function makeDir(name, then) {
    const fs = require('fs');

    try {
        if (fs.existsSync(name)) {
            then();
        } else {
            fs.mkdir(name, (error) => {
                if (error) reject(error);
                else then();
            });
        }
    } catch (error) {
        reject(error);
    }
}

function unpackBase64File(filename, content) {
    const fs = require('fs');

    fs.writeFile(filename, Buffer.from(content, 'base64'), (error) => {
        if (error) reject(error);
    });
}


