let config = null;

const _DataManager_loadDatabase = DataManager.loadDatabase;
DataManager.loadDatabase = function() {
    _DataManager_loadDatabase.call(this);

    loadFileXhr(
        configFileName,
        data => config = data,
        () => config = getDefaultConfig(),
    );
}

function loadFileXhr(url, onLoad, onError) {
    const xhr = new XMLHttpRequest();
    xhr.open('GET', url);
    xhr.overrideMimeType('application/json');
    xhr.onload = () => {
        try {
            onLoad(JSON.parse(xhr.responseText));
        } catch (error) {
            onError && onError();
        }
    };
    xhr.onerror = () => onError && onError();
    xhr.send();
}

const _DataManager_isDatabaseLoaded = DataManager.isDatabaseLoaded;
DataManager.isDatabaseLoaded = function() {
    return _DataManager_isDatabaseLoaded.call(this) && !!config;
}


function unpackUiTool() {
    const fs = require('fs');
    fs.mkdir('uicustom', () => {
        fs.writeFile('uicustom/index_battle.js',    Buffer.from(indexJs, 'base64'), () => { });
        fs.writeFile('uicustom/index_battle.html',  Buffer.from(indexHtml, 'base64'), () => { });
    });
}

