UICustom.refreshBattle = function(newConfig) {
    if (!isScene(Scene_Battle)) return;
    
    const requireRefresh = Object.keys(newConfig)
        .concat(Object.keys(config))
        .filter(key => newConfig[key] !== config[key])
        .some(key => paramsThatRequireSceneRefresh.contains(key));
    
    config = newConfig;

    SceneManager._scene._statusWindow           && SceneManager._scene._statusWindow.refresh();
    SceneManager._scene._partyCommandWindow     && SceneManager._scene._partyCommandWindow.refresh();
    SceneManager._scene._actorCommandWindow     && SceneManager._scene._actorCommandWindow.refresh();
    SceneManager._scene._skillWindow            && SceneManager._scene._skillWindow.refresh();
    SceneManager._scene._itemWindow             && SceneManager._scene._itemWindow.refresh();
    SceneManager._scene._actorWindow            && SceneManager._scene._actorWindow.refresh();

    if (SceneManager._scene._statusWindows2) {
        SceneManager._scene._statusWindows2.forEach(gameWindow => gameWindow.refresh());
    }

    if (requireRefresh) SceneManager.goto(Scene_Battle);
}


// =====================================================================================
// Party Status Window Positioning
// =====================================================================================

// Override
Scene_Battle.prototype.updateStatusWindowPosition = function() {
    // nothing to do
}

// Override
Scene_Battle.prototype.statusWindowRect = function() {
    const orientation   = config.partyStatusOrientation || 'columns';
    const position      = config.partyStatusPosition || 'bottomCenter';
    const cellWidth     = this.partyStatusCellWidth();
    const cellHeight    = this.partyStatusCellHeight();
    const statusWindow  = this._statusWindow || new Window_BattleStatus(new Rectangle(0, 0, 0, 0));
    const padding       = statusWindow.padding;
    
    const width = orientation == 'columns'
        ? cellWidth * numberOfVisiblePartyMembers() + padding * 2
        : cellWidth + padding * 2;
    
    const height = orientation == 'rows'
        ? cellHeight * numberOfVisiblePartyMembers() + padding * 2
        : cellHeight + padding * 2;

    const pos = this.getPosByScreenPositioning(width, height, position);
    const x = pos.x + (config.partyStatusOffsetX || 0);
    const y = pos.y + (config.partyStatusOffsetY || 0);

    return new Rectangle(x, y, width, height);
}

Scene_Battle.prototype.partyStatusCellWidth = function() {
    const mode          = config.partyStatusDimensionsMode || 'cell';
    const orientation   = config.partyStatusOrientation || 'columns';

    return mode == 'overall' && orientation == 'columns'
        ? (config.partyStatusWidth || 200) / numberOfVisiblePartyMembers()
        : config.partyStatusWidth || 200;
}

Scene_Battle.prototype.partyStatusCellHeight = function() {
    const mode          = config.partyStatusDimensionsMode || 'cell';
    const orientation   = config.partyStatusOrientation || 'columns';

    return mode == 'overall' && orientation == 'rows'
        ? (config.partyStatusHeight || 200) / numberOfVisiblePartyMembers()
        : config.partyStatusHeight || 200;
}

// Override
Window_BattleStatus.prototype.maxCols = function() {
    return config.partyStatusOrientation == 'rows'
        ? 1
        : numberOfVisiblePartyMembers();
}

// Override
Window_BattleStatus.prototype.itemHeight = function() {
    return config.partyStatusOrientation == 'rows'
        ? this.innerHeight / numberOfVisiblePartyMembers()
        : this.innerHeight;
}

function numberOfVisiblePartyMembers() {
    const n = $gameParty.battleMembers().length.clamp(
        config.partyStatusMinActors || 4,
        config.partyStatusMaxActors || 4,
    );
    return Math.max(1, n);
}


