const _SceneBattle_update = Scene_Battle.prototype.update;
Scene_Battle.prototype.update = function() {
    _SceneBattle_update.call(this);

    this.relocatePartyStatusWindow();
    this.relocateActorWindow();
    this.relocatePartyCommands();
    this.relocateActorCommands();
    this.relocateSkillList();
    this.relocateItemList();
    this.relocateEnemyWindow();
    this.relocateHelpWindow();
    this.relocateLogWindow();
}

Scene_Battle.prototype.relocatePartyStatusWindow = function() {
    const rect      = this.statusWindowRect();
    const targetX   = this.statusWindowTargetX();
    const targetY   = this.statusWindowTargetY();
    const speed     = 16;

    if (this._statusWindow.x < targetX) {
        this._statusWindow.x = Math.min(this._statusWindow.x + speed, targetX);
    }
    if (this._statusWindow.x > targetX) {
        this._statusWindow.x = Math.max(this._statusWindow.x - speed, targetX);
    }
    if (this._statusWindow.y < targetY) {
        this._statusWindow.y = Math.min(this._statusWindow.y + speed, targetY);
    }
    if (this._statusWindow.y > targetY) {
        this._statusWindow.y = Math.max(this._statusWindow.y - speed, targetY);
    }

    if (this._statusWindow.width != rect.width || this._statusWindow.height != rect.height) {
        this._statusWindow.width = rect.width;
        this._statusWindow.height = rect.height;
        this._statusWindow.refresh();
    }
}

Scene_Battle.prototype.statusWindowTargetX = function() {
    return this.statusWindowRect().x;
}

Scene_Battle.prototype.statusWindowTargetY = function() {
    return this.statusWindowRect().y;
}

Scene_Battle.prototype.relocateActorWindow = function() {
    const rect = this.statusWindowRect();

    this._actorWindow.x = rect.x;
    this._actorWindow.y = rect.y;

    if (this._actorWindow.width != rect.width || this._actorWindow.height != rect.height) {
        this._actorWindow.width = rect.width;
        this._actorWindow.height = rect.height;
        this._actorWindow.refresh();
    }
}

Scene_Battle.prototype.relocatePartyCommands = function() {
    const rect = this.partyCommandWindowRect();

    if (this._partyCommandWindow.width != rect.width || this._partyCommandWindow.height != rect.height) {
        this._partyCommandWindow.width = rect.width;
        this._partyCommandWindow.height = rect.height;
        this._partyCommandWindow.refresh();
    }
    
    this.relocateCommonWindow(
        this._partyCommandWindow,
        config.partyCommandsPositionMode || 'screen',
        config.partyCommandsPosition || 'middleCenter',
        config.partyCommandsOrigin || 'bottomCenter',
        config.partyCommandsOrigin2 || 'topCenter',
        config.partyCommandsOffsetX,
        config.partyCommandsOffsetY,
        config.partyCommandsDashHorz,
        config.partyCommandsDashVert,
    );
}

Scene_Battle.prototype.relocateActorCommands = function() {
    const rect = this.actorCommandWindowRect();

    if (this._actorCommandWindow.width != rect.width || this._actorCommandWindow.height != rect.height) {
        this._actorCommandWindow.width = rect.width;
        this._actorCommandWindow.height = rect.height;
        this._actorCommandWindow.refresh();
    }
    
    this.relocateCommonWindow(
        this._actorCommandWindow,
        config.actorCommandsPositionMode || 'statusWindowActorIndex',
        config.actorCommandsPosition || 'middleLeft',
        config.actorCommandsOrigin || 'bottomCenter',
        config.actorCommandsOrigin2 || 'topCenter',
        config.actorCommandsOffsetX,
        config.actorCommandsOffsetY,
        config.actorCommandsDashHorz,
        config.actorCommandsDashVert,
    );
}

