// Override
Window_BattleStatus.prototype.drawItemImage = function(index) {
    const key       = "actor%1-face".format(index);
    const sprite    = this.createInnerSprite(key, Sprite_Face);
    
    sprite.setup(this.actor(index));
    sprite.move(this.faceRect(index).x, this.faceRect(index).y);
    sprite.show();
}

// Override
Window_BattleStatus.prototype.faceRect = function(index) {
    const scale = this.faceScale(index);
    
    const faceWidth = typeof config.actorPortraitMaxWidth == 'number'
        ? Math.min(config.actorPortraitMaxWidth, ImageManager.faceWidth)
        : ImageManager.faceWidth;
    
    const faceHeight = typeof config.actorPortraitMaxHeight == 'number'
        ? Math.min(config.actorPortraitMaxHeight, ImageManager.faceHeight)
        : ImageManager.faceHeight;
    
    const pos = getPosByDirection(
        this.itemWidth(),
        this.itemHeight(),
        faceWidth * scale,
        faceHeight * scale,
        config.actorPortraitPosition || 'topCenter',
    );
    const x = pos.x + this.itemRect(index).x + (config.actorPortraitOffsetX || 0);
    const y = pos.y + this.itemRect(index).y + (config.actorPortraitOffsetY || 0);

    return new Rectangle(x, y, faceWidth * scale, faceHeight * scale);
}

Window_BattleStatus.prototype.faceScale = function(/*index*/) {
    return typeof config.actorPortraitScale === 'number'
        ? config.actorPortraitScale / 100.0
        : 1.0;
}

function Sprite_Face() {
    this.initialize.apply(this, arguments);
}

Sprite_Face.prototype = Object.create(Sprite.prototype);
Sprite_Face.prototype.constructor = Sprite_Face;

Sprite_Face.prototype.setup = function(actor) {
    this._actor = actor;
}

Sprite_Face.prototype.actor = function() {
    return this._actor;
}

Sprite_Face.prototype.getBitmap = function() {
    return this.actor()
        ? ImageManager.loadFace(this.actor().faceName())
        : undefined;
}

Sprite_Face.prototype.update = function() {
    Sprite.prototype.update.call(this);

    this.updateBitmapIfNeeded();
    this.updateFrame();
    this.updateScale();

    this.visible = this.isVisible();
    this.updateKnockoutEffect();
}

Sprite_Face.prototype.updateBitmapIfNeeded = function() {
    if (this.bitmap != this.getBitmap()) {
        this.bitmap = this.getBitmap();
    }
}

Sprite_Face.prototype.updateFrame = function() {
    if (this.bitmap && this.actor()) {
        const faceWidth = typeof config.actorPortraitMaxWidth == 'number'
            ? Math.min(config.actorPortraitMaxWidth, ImageManager.faceWidth)
            : ImageManager.faceWidth
        
        const faceHeight = typeof config.actorPortraitMaxHeight == 'number'
            ? Math.min(config.actorPortraitMaxHeight, ImageManager.faceHeight)
            : ImageManager.faceHeight;
        
        const gapX = ImageManager.faceWidth - faceWidth;
        const gapY = ImageManager.faceHeight - faceHeight;
        const x = (this.actor().faceIndex() % 4) * ImageManager.faceWidth + gapX / 2;
        const y = Math.floor(this.actor().faceIndex() / 4) * ImageManager.faceHeight + gapY / 2;

        if (!this.frame || this.frame.x != x || this.frame.y != y || this.frame.width != faceWidth || this.frame.height != faceHeight) {
            this.setFrame(x, y, faceWidth, faceHeight);
        }
    }
}

Sprite_Face.prototype.updateScale = function() {
    this.scale.x = this.getScale();
    this.scale.y = this.getScale();
}

Sprite_Face.prototype.getScale = function() {
    return typeof config.actorPortraitScale === 'number'
        ? config.actorPortraitScale / 100.0
        : 1.0;
}

Sprite_Face.prototype.isVisible = function() {
    const mode = config.actorPortraitMode || 'face';
    
    return (
        mode == 'face' &&
        this.getBitmap()
    );
}

Sprite_Face.prototype.updateKnockoutEffect = function() {
    // nothing to do
}



