Window_BattleStatus.prototype.nameX = function(rect) {
    return rect.x + (config.actorNameOffsetX || 0);
}

Window_BattleStatus.prototype.nameY = function(rect) {
    const nameHeight    = this.textHeightByFontSize(config.actorNameFontSize);
    const vertAlign     = config.actorNameVertAlign || 'top';
    let y;

    if (vertAlign == 'top')     y = rect.y;
    if (vertAlign == 'middle')  y = rect.height / 2 - nameHeight / 2 + rect.y;
    if (vertAlign == 'bottom')  y = rect.height - nameHeight + rect.y;

    return y + (config.actorNameOffsetY || 0);
}


const _SpriteName_bitmapWidth = Sprite_Name.prototype.bitmapWidth;
Sprite_Name.prototype.bitmapWidth = function() {
    return typeof config.actorNameWidth == 'number'
        ? config.actorNameWidth
        : _SpriteName_bitmapWidth.call(this);
}

const _SpriteName_fontSize = Sprite_Name.prototype.fontSize;
const _SpriteName_bitmapHeight = Sprite_Name.prototype.bitmapHeight;
Sprite_Name.prototype.bitmapHeight = function() {
    const originalFontSize  = _SpriteName_fontSize.call(this);
    const thisFontSize      = this.fontSize();
    const factor            = thisFontSize / originalFontSize;

    return Math.floor(factor * _SpriteName_bitmapHeight.call(this));
}

const _SpriteName_updateBitmap = Sprite_Name.prototype.updateBitmap;
Sprite_Name.prototype.updateBitmap = function() {
    if (this.bitmap.width != this.bitmapWidth() || this.bitmap.height != this.bitmapHeight()) {
        this.bitmap = new Bitmap(this.bitmapWidth(), this.bitmapHeight());
    }
    _SpriteName_updateBitmap.call(this);
}

// Override
Sprite_Name.prototype.redraw = function() {
    this.bitmap.clear();
    
    this.setupFont();
    this.drawBackground();

    this.bitmap.drawText(
        this.name(),
        4,
        0,
        this.bitmapWidth() - 8,
        this.bitmapHeight(),
        config.actorNameTextAlign || 'left',
    );
}

Sprite_Name.prototype.drawBackground = function() {
    if (config.actorNameBackgroundType == 'image' && this.getBackgroundBitmap()) {
        const bitmap = this.getBackgroundBitmap();

        if (bitmap.isReady()) {
            this.bitmap.blt(
                bitmap,
                0,
                0,
                bitmap.width,
                bitmap.height,
                0,
                0,
                this.bitmap.width,
                this.bitmap.height,
            );
        } else {
            bitmap.addLoadListener(this.redraw.bind(this));
        }
    }

    if (config.actorNameBackgroundType == 'gradient') {
        this.drawHorzGradient(
            0,
            0,
            this.bitmap.width,
            this.bitmap.height,
            config.actorNameTextAlign || 'left',
            ColorManager.dimColor1(),
            ColorManager.dimColor2(),
        );
    }
}

Sprite_Name.prototype.getBackgroundBitmap = function() {
    return ImageManager.loadBitmapFromFilepath(this.getBitmapFilename());
}

Sprite_Name.prototype.getBitmapFilename = function() {
    return config.actorNameBackgroundFile;
}

const _SpriteName_update = Sprite_Name.prototype.update;
Sprite_Name.prototype.update = function() {
    _SpriteName_update.call(this);

    this.visible = this.isVisible();
}

Sprite_Name.prototype.isVisible = function() {
    return (
        this._battler && this._battler.isBattleMember() &&
        !config.hideActorName
    );
}


const _WindowBattleStatus_refresh = Window_BattleStatus.prototype.refresh;
Window_BattleStatus.prototype.refresh = function() {
    _WindowBattleStatus_refresh.call(this);

    recursivelyRedraw(this);
}

function recursivelyRedraw(sprite) {
    if (sprite.redraw) sprite.redraw();
    
    if (sprite.children) {
        sprite.children.forEach(recursivelyRedraw)
    }
}


