// Override
Window_BattleStatus.prototype.placeBasicGauges = function(actor, /*x, y*/) {
    const showHp = this.showHp(actor);
    const showMp = this.showMp(actor);
    const showTp = this.showTp(actor);

    const hpGaugePos = this.hpGaugePos(actor);
    const mpGaugePos = this.mpGaugePos(actor);
    const tpGaugePos = this.tpGaugePos(actor);

    if (showHp) this.placeGauge(actor, 'hp', hpGaugePos.x, hpGaugePos.y);
    if (showMp) this.placeGauge(actor, 'mp', mpGaugePos.x, mpGaugePos.y);
    if (showTp) this.placeGauge(actor, 'tp', tpGaugePos.x, tpGaugePos.y);
}

