    const dummySprite = new Sprite_Gauge();
    dummySprite.setup(actor, statusType);
    
    const pos = getPosByDirection(
        this.itemRect(actor.index()).width,
        this.itemRect(actor.index()).height,
        dummySprite.width,
        dummySprite.height,
        direction|| 'middleLeft',
    );
    const x = pos.x + this.itemRect(actor.index()).x + dx;
    const y = pos.y + this.itemRect(actor.index()).y + dy;

    return { x, y };
