// Core Code Flashing Fix
const _WindowPartyCommand_open = Window_PartyCommand.prototype.open;
Window_PartyCommand.prototype.open = function() {
    this._mk_partyCommandOpenFlag = 0;

    _WindowPartyCommand_open.call(this);
}

const _WindowPartyCommand_updateOpen = Window_PartyCommand.prototype.updateOpen;
Window_PartyCommand.prototype.updateOpen = function() {
    if (this._mk_partyCommandOpenFlag > 3) {
        _WindowPartyCommand_updateOpen.call(this);
    } else {
        this._mk_partyCommandOpenFlag += 1;
    }
}


