Window_ActorCommand.prototype.commandIcon = function(index) {
    if (this.commandSymbol(index) == 'attack')  return icons.attackIcon;
    if (this.commandSymbol(index) == 'guard')   return icons.guardIcon;
    if (this.commandSymbol(index) == 'item')    return icons.itemIcon;

    if (this.commandSymbol(index) == 'skill') {
        const stypeId = this._list[index] ? this._list[index].ext : 0;
        return icons.skillIcons[stypeId];
    }
}


