{
    const _SceneBoot_start = Scene_Boot.prototype.start;
    Scene_Boot.prototype.start = function() {
        _SceneBoot_start.call(this);

        Window_BattleStatus.prototype.drawItemStatusXPStyle = function(index) {
            const actor = this.actor(index);
            const rect = this.itemRectWithPadding(index);
            const nameX = this.nameX(rect);
            const nameY = this.nameY(rect);
            const stateIconX = this.stateIconX(rect);
            const stateIconY = this.stateIconY(rect);
            const basicGaugesX = this.basicGaugesX(rect);
            const basicGaugesY = this.basicGaugesY(rect);
            
            this.placeTimeGauge(actor, nameX, nameY);
            this.placeActorName(actor, nameX, nameY);
            this.placeStateIcon(actor, stateIconX, stateIconY);
            this.placeBasicGauges(actor, basicGaugesX, basicGaugesY);
        }

        Window_BattleStatus.prototype.drawItemStatusListStyle = Window_BattleStatus.prototype.drawItemStatusXPStyle;
    }

    const _WindowPartyCommand_activate = Window_PartyCommand.prototype.activate;
    Window_PartyCommand.prototype.activate = function() {
        _WindowPartyCommand_activate.call(this);

        this.show();
    }

    const _WindowActorCommand_activate = Window_ActorCommand.prototype.activate;
    Window_ActorCommand.prototype.activate = function() {
        _WindowActorCommand_activate.call(this);

        this.show();
    }
}


